package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity; import com.primehr.shared.exception.IllegalLifecycleTransitionException; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="prime_committee",uniqueConstraints=@UniqueConstraint(name="uk_prime_committee_version",columnNames={"agency_id","normalized_code","definition_version"}))
public class Committee extends RspAuditedEntity {
 public enum Type { HRMPSB } public enum Status { DRAFT,PUBLISHED,SUPERSEDED }
 @Column(nullable=false,length=80) private String code; @Column(name="normalized_code",nullable=false,length=80) private String normalizedCode; @Enumerated(EnumType.STRING) @Column(name="committee_type",nullable=false,length=30) private Type type; @Column(nullable=false,length=200) private String name; @Column(name="legal_basis",nullable=false,length=1000) private String legalBasis; @Column(name="definition_version",nullable=false) private int definitionVersion; @Column(name="supersedes_id",length=36) private String supersedesId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status; @Column(name="effective_from") private LocalDate effectiveFrom; @Column(name="effective_to") private LocalDate effectiveTo; @Column(name="minimum_voting_members",nullable=false) private int minimumVotingMembers; @Column(name="published_by",length=100) private String publishedBy; @Column(name="published_at") private Instant publishedAt;
 protected Committee(){}
 public Committee(String agency,String code,String name,String basis,int minimum,int version,String prior){super(agency);if(version<1)throw new IllegalArgumentException("definitionVersion must be positive");definitionVersion=version;supersedesId=optionalText(prior);type=Type.HRMPSB;status=Status.DRAFT;apply(code,name,basis,minimum);}
 public void update(String code,String name,String basis,int minimum){requireDraft();apply(code,name,basis,minimum);}
 public void publish(LocalDate from,LocalDate to,String actor,Instant at){requireDraft();if(from==null)throw new IllegalArgumentException("effectiveFrom is required");if(to!=null&&to.isBefore(from))throw new IllegalArgumentException("effectiveTo cannot precede effectiveFrom");effectiveFrom=from;effectiveTo=to;publishedBy=requiredText(actor,"actor");publishedAt=Objects.requireNonNull(at);status=Status.PUBLISHED;}
 public void supersede(LocalDate next){if(status!=Status.PUBLISHED)throw new IllegalLifecycleTransitionException("Only PUBLISHED committees may be superseded");if(next==null||!next.isAfter(effectiveFrom))throw new IllegalArgumentException("A successor must become effective after its predecessor");LocalDate end=next.minusDays(1);if(effectiveTo==null||effectiveTo.isAfter(end))effectiveTo=end;status=Status.SUPERSEDED;}
 public boolean effectiveOn(LocalDate date){return (status==Status.PUBLISHED||status==Status.SUPERSEDED)&&!date.isBefore(effectiveFrom)&&(effectiveTo==null||!date.isAfter(effectiveTo));}
 private void apply(String c,String n,String b,int minimum){code=requiredText(c,"code");normalizedCode=code.toUpperCase(Locale.ROOT);name=requiredText(n,"name");legalBasis=requiredText(b,"legalBasis");if(minimum<1)throw new IllegalArgumentException("minimumVotingMembers must be positive");minimumVotingMembers=minimum;}
 private void requireDraft(){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Published committees are immutable; create a successor");}
 public String getCode(){return code;} public String getNormalizedCode(){return normalizedCode;} public Type getType(){return type;} public String getName(){return name;} public String getLegalBasis(){return legalBasis;} public int getDefinitionVersion(){return definitionVersion;} public String getSupersedesId(){return supersedesId;} public Status getStatus(){return status;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public LocalDate getEffectiveTo(){return effectiveTo;} public int getMinimumVotingMembers(){return minimumVotingMembers;} public String getPublishedBy(){return publishedBy;} public Instant getPublishedAt(){return publishedAt;}
}
